:root {
  --card-bg: #fdf6ee;
  --card-border: #b8956a;
  --header-bg: #7a2c2c;
  --header-text: #f9ede0;
  --badge-bg: #f0d9b5;
  --badge-text: #7a2c2c;
  --title-color: #3b1f10;
  --provenance-color: #7a5c3c;
  --label-color: #9c7450;
  --value-color: #3b1f10;
  --aside-bg: #f4e8d6;
  --aside-border: #c9a97a;
  --estimate-color: #7a2c2c;
  --reserve-color: #4a3020;
  --dot-color: #4a8a50;
  --footer-bg: #ede0ce;
  --footer-text: #7a5c3c;
  --divider-color: #c9a97a;
}

article.lot-card {
  background: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 6px;
  width: 460px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.lot-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
}

.lot-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  padding: 2px 7px;
  border-radius: 3px;
}

.lot-number {
  color: var(--header-text);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.lot-divider {
  color: var(--divider-color);
  font-size: 14px;
}

.lot-session {
  color: var(--header-text);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0.06em;
  opacity: 0.85;
}

.lot-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  flex: 1;
}

.lot-main {
  flex: 1;
  padding: 14px 16px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.lot-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--title-color);
  line-height: 1.25;
  margin: 0;
}

.lot-provenance {
  font-size: 12px;
  color: var(--provenance-color);
  margin: 0;
  font-style: italic;
  line-height: 1.4;
}

.lot-details {
  list-style: none;
  margin: 6px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.lot-details li {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: 12px;
  line-height: 1.4;
}

.detail-label {
  color: var(--label-color);
  font-weight: 600;
  min-width: 68px;
  letter-spacing: 0.03em;
}

.detail-value {
  color: var(--value-color);
  font-weight: 400;
}

.lot-aside {
  width: 130px;
  background: var(--aside-bg);
  border-left: 1px solid var(--aside-border);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 10px;
}

.estimate-block,
.reserve-block {
  text-align: center;
}

.estimate-label,
.reserve-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--label-color);
  margin: 0 0 2px;
  text-transform: uppercase;
}

.estimate-range {
  font-size: 13px;
  font-weight: 700;
  color: var(--estimate-color);
  margin: 0;
  line-height: 1.3;
}

.reserve-price {
  font-size: 13px;
  font-weight: 600;
  color: var(--reserve-color);
  margin: 0;
}

.condition-badge {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 600;
  color: var(--value-color);
  background: var(--card-bg);
  border: 1px solid var(--aside-border);
  border-radius: 10px;
  padding: 3px 9px;
}

.condition-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--dot-color);
  display: inline-block;
}

.lot-footer {
  background: var(--footer-bg);
  border-top: 1px solid var(--card-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 16px;
}

.footer-house {
  font-size: 11px;
  font-weight: 700;
  color: var(--footer-text);
  letter-spacing: 0.05em;
}

.footer-date {
  font-size: 11px;
  color: var(--footer-text);
  font-style: italic;
}
